/bin/bash -c "python3 - <<'PY'
import glob,os
try:
 from bs4 import BeautifulSoup
 print('bs4 yes')
 for f in glob.glob(os.path.join(os.environ['TMPDIR'],'ajaigarh-*.html')):
  if any(x in os.path.basename(f) for x in ['U4e7','NoVj','C3829','ZMid','vjGd','ihb4','regular']):
   s=BeautifulSoup(open(f,encoding='utf-8',errors='ignore'),'html.parser')
   print('\\n===',os.path.basename(f),'===')
   for tag in s.find_all(['h1','h2','h3','th','td','p','div']):
    t=' '.join(tag.get_text(' ',strip=True).split())
    if t and len(t)<300 and (tag.name in ['h1','h2','h3','th','td'] or tag.get('class') and ('container' in tag.get('class') or 'page-title' in tag.get('class'))): print(t)
except Exception as e: print(e)
PY"

